import json
from pathlib import Path

source = Path('/data/events.jsonl')
out_dir = Path('/out')
rows = []
errors = []


def reject_constant(value):
    raise ValueError(f'non-standard JSON constant: {value}')


def flatten(obj, prefix='', result=None):
    if result is None:
        result = {}
    for key, value in obj.items():
        full_key = f'{prefix}.{key}' if prefix else key
        if isinstance(value, dict):
            flatten(value, full_key, result)
        else:
            result[full_key] = value
    return result


def cell(value):
    if value is None:
        return ''
    if isinstance(value, str):
        return value
    if isinstance(value, bool):
        return 'true' if value else 'false'
    if isinstance(value, list):
        return json.dumps(value, ensure_ascii=False, separators=(',', ':'))
    return json.dumps(value)


def csv_field(value):
    if any(ch in value for ch in (',', '"', '\n')):
        return '"' + value.replace('"', '""') + '"'
    return value


with source.open('r', encoding='utf-8') as f:
    for line_number, line in enumerate(f, 1):
        if not line.strip():
            continue
        try:
            value = json.loads(line, parse_constant=reject_constant)
        except (json.JSONDecodeError, ValueError):
            errors.append(f'line {line_number}')
            continue
        if not isinstance(value, dict):
            errors.append(f'line {line_number}')
            continue
        rows.append(flatten(value))

columns = sorted({key for row in rows for key in row})
with (out_dir / 'events.csv').open('w', encoding='utf-8', newline='') as f:
    f.write(','.join(csv_field(key) for key in columns) + '\n')
    for row in rows:
        f.write(','.join(csv_field(cell(row.get(key))) for key in columns) + '\n')

with (out_dir / 'errors.txt').open('w', encoding='utf-8', newline='') as f:
    if errors:
        f.write('\n'.join(errors) + '\n')
